const topics = [
  { title: 'Thói quen uống nước hợp lý', topic: 'Sức khỏe hằng ngày' },
  { title: 'Tầm quan trọng của giấc ngủ', topic: 'Giấc ngủ' },
  { title: 'Lợi ích của vận động thường xuyên', topic: 'Vận động' },
  { title: 'Cách xây dựng bữa ăn cân bằng', topic: 'Dinh dưỡng' },
  { title: 'Thói quen vệ sinh giúp bảo vệ sức khỏe', topic: 'Phòng ngừa bệnh' }
];

// Dữ liệu đầu vào từ Schedule Trigger hoặc Webhook Trigger
const input = $input.first().json;

// Webhook n8n thường đặt dữ liệu POST trong input.body
const body = input.body && typeof input.body === 'object'
  ? input.body
  : {};

// Chỉ nhận các chuỗi hợp lệ
function cleanText(value, maxLength) {
  return typeof value === 'string'
    ? value.trim().slice(0, maxLength)
    : '';
}

const customTopic = cleanText(body.topic, 150);
const customTitle = cleanText(body.suggestedTitle, 200);

// Nếu không có chủ đề từ Webhook, tự chọn theo ngày
const dayIndex = Math.floor(Date.now() / 86400000);
const selected = topics[dayIndex % topics.length];

const isManual = customTopic.length > 0;

return [{
  json: {
    topic: isManual ? customTopic : selected.topic,
    suggestedTitle: isManual
      ? (customTitle || customTopic)
      : selected.title,
    language: 'Vietnamese',
    audience: 'Độc giả ở nhiều độ tuổi',
    triggerMode: isManual ? 'MANUAL' : 'SCHEDULE'
  }
}];

