const response = $json.message?.content;

if (!response) {
  throw new Error("Ollama không trả về nội dung bài viết");
}

let article;

try {
  article = typeof response === "string"
    ? JSON.parse(response)
    : response;
} catch (error) {
  throw new Error("Không thể phân tích JSON từ Ollama: " + error.message);
}

const title = article.title?.trim();
const topic = article.topic?.trim();
const body = (article.body || article.content)?.trim();

if (!title || !topic || !body) {
  throw new Error("Bài viết thiếu title, topic hoặc body");
}

return {
  json: {
    title,
    topic,
    body,
    sourceUrls: Array.isArray(article.sourceUrls)
      ? article.sourceUrls
      : [],
    status: "PENDING_REVIEW"
  }
};

const article = $json;

const errors = [];

if (
  typeof article.title !== "string" ||
  article.title.trim().length < 10
) {
  errors.push("Tiêu đề không hợp lệ hoặc quá ngắn");
}

if (
  typeof article.topic !== "string" ||
  article.topic.trim().length === 0
) {
  errors.push("Thiếu chủ đề bài viết");
}

if (
  typeof article.body !== "string" ||
  article.body.trim().length < 100
) {
  errors.push("Nội dung bài viết không hợp lệ hoặc quá ngắn");
}

if (!Array.isArray(article.sourceUrls)) {
  errors.push("sourceUrls phải là một mảng");
} else {
  for (const url of article.sourceUrls) {
    try {
      const parsedUrl = new URL(url);

      if (!["http:", "https:"].includes(parsedUrl.protocol)) {
        errors.push("URL nguồn không hợp lệ");
        break;
      }
    } catch {
      errors.push("URL nguồn không đúng định dạng");
      break;
    }
  }
}

return {
  json: {
    ...article,
    isValid: errors.length === 0,
    validationErrors: errors
  }
};

