const raw = $json.message?.content;

if (!raw) {
  throw new Error("Ollama không trả về kết quả kiểm duyệt");
}

let review;

try {
  review = JSON.parse(raw);
} catch (error) {
  throw new Error("Không thể phân tích kết quả kiểm duyệt: " + error.message);
}

const article = $("Validate Content1").item.json;

const allowedDecisions = [
  "APPROVED",
  "NEEDS_REVIEW",
  "REJECTED"
];

if (!allowedDecisions.includes(review.decision)) {
  throw new Error("Kết quả kiểm duyệt không hợp lệ");
}

return {
  json: {
    ...article,
    medicalReview: {
      decision: review.decision,
      medicalIssues: review.medicalIssues || [],
      explanation: review.explanation || ""
    }
  }
};

const article = $json;

return {
  json: {
    ...article,
    status: "PENDING_REVIEW",
    reviewStatus: "WAITING_FOR_HUMAN",
    requiresHumanReview: true,
    reviewMessage:
      "Bài viết có vấn đề y tế cần được con người kiểm tra trước khi phê duyệt."
  }
};

